package com.hospital.finance.auth;
import com.hospital.dao.LoginMapper;
import com.hospital.entity.Login;
import com.hospital.service.impl.LoginServiceImpl;
import org.junit.jupiter.api.*;
import org.mockito.ArgumentCaptor;
import org.springframework.test.util.ReflectionTestUtils;
import java.util.Collections;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
class AdminCredentialMigrationTest {
    LoginMapper mapper; LoginServiceImpl service;
    @BeforeEach void setup(){mapper=mock(LoginMapper.class);service=new LoginServiceImpl();ReflectionTestUtils.setField(service,"loginMapper",mapper);}
    Login account(int role,String password){Login a=new Login();a.setId(1);a.setRole(role);a.setUsername("synthetic");a.setPassword(password);return a;}
    Login attempt(String password){Login a=account(99,password);return a;}
    @Test void adminReadModelsOmitPlaintextAndHashesWithoutMutatingStorage(){for(String password:new String[]{"123456",LoginPasswordCodec.encode("new-only-123")}){Login a=account(1,password);when(mapper.selectByPrimaryKey(1)).thenReturn(a);when(mapper.findAllAdmin(null)).thenReturn(Collections.singletonList(a));assertNull(service.getAdmin(1).getPassword());assertNull(service.findAllAdmin(null).get(0).getPassword());assertEquals(password,a.getPassword());}when(mapper.selectByPrimaryKey(1)).thenReturn(account(2,"123456"));assertNull(service.getAdmin(1));}
    @Test void newAdminHashesWithoutChangingInputAndRejectsWeakNewPassword(){when(mapper.insertAdmin(any())).thenReturn(1);Login input=attempt("new-only-123");assertEquals("添加成功",service.addAmin(input));ArgumentCaptor<Login> captured=ArgumentCaptor.forClass(Login.class);verify(mapper).insertAdmin(captured.capture());assertNotEquals(input.getPassword(),captured.getValue().getPassword());assertTrue(LoginPasswordCodec.matches(captured.getValue().getPassword(),input.getPassword()));assertNull(captured.getValue().getRole());assertEquals("new-only-123",input.getPassword());assertTrue(service.addAmin(attempt("123456")).contains("8至72"));verify(mapper,times(1)).insertAdmin(any());}
    @Test void blankEditPreservesAndChangedPasswordHashes(){Login stored=account(1,"old-value");when(mapper.selectByPrimaryKey(1)).thenReturn(stored);when(mapper.findByUsername("synthetic")).thenReturn(stored);when(mapper.updateByPrimaryKeySelective(any())).thenReturn(1);assertEquals("更新成功",service.updateAdmin(attempt("")));ArgumentCaptor<Login> c=ArgumentCaptor.forClass(Login.class);verify(mapper).updateByPrimaryKeySelective(c.capture());assertNull(c.getValue().getPassword());assertEquals("更新成功",service.updateAdmin(attempt("changed-123")));verify(mapper,times(2)).updateByPrimaryKeySelective(c.capture());assertTrue(LoginPasswordCodec.matches(c.getValue().getPassword(),"changed-123"));assertEquals("old-value",stored.getPassword());}
    @Test void correctShortLegacyCredentialsMigrateForEveryStoredRole(){for(int role:new int[]{1,2,3}){reset(mapper);when(mapper.findByUsername("synthetic")).thenReturn(account(role,"123456"));when(mapper.migratePassword(eq(1),eq("123456"),anyString())).thenReturn(1);Login input=attempt("123456");assertEquals("登录成功"+role,service.login(input));assertEquals(role,input.getRole());ArgumentCaptor<String> encoded=ArgumentCaptor.forClass(String.class);verify(mapper).migratePassword(eq(1),eq("123456"),encoded.capture());assertTrue(encoded.getValue().startsWith("pbkdf2$"));assertTrue(LoginPasswordCodec.matches(encoded.getValue(),"123456"));}}
    @Test void wrongPasswordNeverMigratesOrKeepsForgedIdentity(){when(mapper.findByUsername("synthetic")).thenReturn(account(1,"123456"));Login input=attempt("wrong");assertEquals("密码错误",service.login(input));assertNull(input.getId());assertNull(input.getRole());verify(mapper,never()).migratePassword(anyInt(),anyString(),anyString());}
    @Test void hashLoginDoesNotDoubleHash(){when(mapper.findByUsername("synthetic")).thenReturn(account(2,LoginPasswordCodec.encode("new-only-123")));assertEquals("登录成功2",service.login(attempt("new-only-123")));verify(mapper,never()).migratePassword(anyInt(),anyString(),anyString());}
    @Test void concurrentResetWinsAndStalePasswordCannotLogin(){when(mapper.findByUsername("synthetic")).thenReturn(account(1,"123456"));when(mapper.selectByPrimaryKey(1)).thenReturn(account(1,LoginPasswordCodec.encode("reset-only-123")));Login input=attempt("123456");assertEquals("密码错误",service.login(input));assertNull(input.getId());verify(mapper,times(1)).migratePassword(eq(1),eq("123456"),anyString());verify(mapper,never()).updateByPrimaryKeySelective(any());}
    @Test void concurrentMigrationRevalidatesLatestIdentity(){when(mapper.findByUsername("synthetic")).thenReturn(account(1,"123456"));when(mapper.selectByPrimaryKey(1)).thenReturn(account(3,LoginPasswordCodec.encodeLegacyVerified("123456")));Login input=attempt("123456");assertEquals("登录成功3",service.login(input));assertEquals(3,input.getRole());}
    @Test void legacyCompatibilityDoesNotWeakenNewPolicy(){assertThrows(IllegalArgumentException.class,()->LoginPasswordCodec.encode("123456"));assertThrows(IllegalArgumentException.class,()->LoginPasswordCodec.encode("x".repeat(73)));assertThrows(IllegalArgumentException.class,()->LoginPasswordCodec.encodeLegacyVerified("x".repeat(257)));String a=LoginPasswordCodec.encodeLegacyVerified("123456"),b=LoginPasswordCodec.encodeLegacyVerified("123456");assertNotEquals(a,b);assertTrue(LoginPasswordCodec.matches(a,"123456"));}
}
